var ANSI = {
  reset: "\x1B[0m",
  bold: "\x1B[1m",
  dim: "\x1B[2m",
  blue: "\x1B[34m",
  brightRed: "\x1B[91m",
  brightGreen: "\x1B[92m",
  brightYellow: "\x1B[93m",
  brightBlue: "\x1B[94m",
  brightMagenta: "\x1B[95m",
  brightCyan: "\x1B[96m",
  brightWhite: "\x1B[97m"
};
function mask(v) {
  if (!v || v.length <= 8) {
    return "••••••••";
  }
  return `${v.slice(0, 4)}${"•".repeat(Math.min(12, v.length - 8))}${v.slice(-4)}`;
}
function fmtVal(value, sensitive, maxLen) {
  let s;
  if (value === undefined || value === null || value === "") {
    s = "(not set)";
  } else if (sensitive) {
    s = mask(String(value));
  } else {
    s = String(value);
  }
  if (s.length > maxLen) {
    s = `${s.slice(0, maxLen - 3)}...`;
  }
  return s;
}
var ANSI_PATTERN = /\x1b\[[0-9;]*m/g;
