// typing.ts
var HEARTBEAT_MS = 9000;
var DEFAULT_MAX_DURATION_MS = 20 * 60 * 1000;
function createTypingController(channel, maxDurationMs = DEFAULT_MAX_DURATION_MS) {
  let interval = null;
  let ttlTimeout = null;
  let stopped = false;
  let started = false;
  const sendTyping = () => {
    if (stopped)
      return;
    try {
      if (channel.sendTyping) {
        channel.sendTyping().catch(() => {});
      }
    } catch {}
  };
  const stop = () => {
    if (stopped)
      return;
    stopped = true;
    if (interval) {
      clearInterval(interval);
      interval = null;
    }
    if (ttlTimeout) {
      clearTimeout(ttlTimeout);
      ttlTimeout = null;
    }
  };
  const start = () => {
    if (started || stopped)
      return;
    started = true;
    sendTyping();
    interval = setInterval(sendTyping, HEARTBEAT_MS);
    ttlTimeout = setTimeout(stop, maxDurationMs);
  };
  return { start, stop };
}

